  function ensureConventionalCatalog(data,version=Number(data.catalogVersion)||1){
    data.materials=Array.isArray(data.materials)?data.materials:[];
    data.machines=Array.isArray(data.machines)?data.machines:[];
    data.operations=Array.isArray(data.operations)?data.operations:[];
    data.projects=Array.isArray(data.projects)?data.projects:[];
    data.settings={...structuredClone(defaults.settings),...(data.settings||{}),exchangeRates:{...defaults.settings.exchangeRates,...(data.settings?.exchangeRates||{})}};
    if(!currencyCatalog[data.settings.currency])data.settings.currency='INR';
    if(version<6){
      if(!data.materials.length)data.materials=structuredClone(materialSeed);
      if(!data.machines.length)data.machines=structuredClone(machineSeed);
      if(!data.operations.length)data.operations=structuredClone(operationSeed);
    }
    if(version<2){
      for(const seed of machineSeed.filter(x=>x.id==='mc-conv-mill'||x.id==='mc-conv-lathe'))if(!data.machines.some(x=>x.id===seed.id||x.name===seed.name))data.machines.push(structuredClone(seed));
      for(const seed of operationSeed.filter(x=>x.id==='op-18'||x.id==='op-19'))if(!data.operations.some(x=>x.id===seed.id||x.name===seed.name))data.operations.push(structuredClone(seed));
    }
    if(version<5)for(const seed of materialSeed.filter(x=>x.id.startsWith('mat-lib-')))if(!data.materials.some(x=>x.id===seed.id||x.name===seed.name))data.materials.push(structuredClone(seed));
    if(version<5)for(const seed of materialSeed.filter(x=>Number.parseFloat(x.assumedPrice)>0)){
      const row=data.materials.find(x=>x.id===seed.id||x.name===seed.name);
      if(row&&!(Number.parseFloat(row.price)>0)&&!(Number.parseFloat(row.assumedPrice)>0))row.assumedPrice=seed.assumedPrice;
      if(row&&seed.id==='mat-lib-peek'&&!(Number.parseFloat(row.price)>0)&&Number.parseFloat(row.assumedPrice)===1500)row.assumedPrice=seed.assumedPrice;
    }
    data.catalogVersion=6;
    return data;
  }
  function loadDb(){try{const raw=localStorage.getItem(STORAGE);if(!raw)return structuredClone(defaults);const saved=JSON.parse(raw),data={...structuredClone(defaults),...saved,materials:Array.isArray(saved.materials)?saved.materials:structuredClone(materialSeed),machines:Array.isArray(saved.machines)?saved.machines:structuredClone(machineSeed),operations:Array.isArray(saved.operations)?saved.operations:structuredClone(operationSeed),projects:Array.isArray(saved.projects)?saved.projects:[]};return ensureConventionalCatalog(data,Number(saved.catalogVersion)||1)}catch{return structuredClone(defaults)}}
