  function updateHeading(page){const labels={dashboard:'Dashboard',estimate:'New estimation',quotations:'Quotations',materials:'Material database',machines:'Machine rates',operations:'Operations',analysis:'Cost analysis',settings:'Settings'};$('#breadcrumb-current').textContent=labels[page]||'Dashboard';$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));$('#sidebar').classList.remove('open');if(page==='dashboard')renderDashboard();if(page==='quotations')renderProjects();if(page==='materials')renderMaterials();if(page==='machines')renderMachines();if(page==='operations')renderOperationTypes();if(page==='analysis')renderAnalysis()}
