    applyScrapDefaults(material,true);
    setAssumedStockDimensions();
    const priorAutoOperation=estimate.operations.find(op=>op.assumed);
    estimate.operations=[assumedOperation(material,estimate.material.form,priorAutoOperation?.id)];
    estimate.extras={...estimate.extras,cutting:0,heat:0,finishing:0,inspection:0,transport:0,packaging:0,overheadPct:10,rejectionPct:2};
