  function renderDashboard(){const projects=db.projects.slice(0,6);$('#recent-projects').innerHTML=projectRows(projects,false);$('#dashboard-empty').classList.toggle('hidden',projects.length>0);$('#recent-projects').closest('.table-wrap').querySelector('table').classList.toggle('hidden',projects.length===0);$('#metric-estimates').textContent=db.projects.length;const now=new Date();const total=db.projects.reduce((s,p)=>{const d=new Date(p.updated||0),c=calculateFor(p);return s+(!c.errors.length&&p.status==='Quoted'&&d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth()?c.batchTotal:0)},0);$('#metric-quoted').textContent=money(total);const complete=db.projects.map(p=>calculateFor(p)).filter(c=>!c.errors.length);$('#metric-margin').textContent=complete.length?`${fmt(complete.reduce((s,c)=>s+(c.netSell?c.profit/c.netSell*100:0),0)/complete.length)}%`:'—';$('#metric-materials').textContent=db.materials.length;$('#dashboard-empty').classList.toggle('hidden',projects.length>0)}
