  function renderMaterials(){const tb=$('#materials-table');tb.innerHTML=db.materials.map((m,i)=>`<tr><td><input class="cell-input wide" data-table="materials" data-index="${i}" data-key="name" value="${esc(m.name)}"></td><td><input class="cell-input" type="number" min="0" data-table="materials" data-index="${i}" data-key="density" value="${esc(m.density)}"></td><td><input class="cell-input" type="number" min="0" data-table="materials" data-index="${i}" data-key="price" value="${num(m.price)>0?esc(m.price):''}" placeholder="${num(m.price)>0?'':`~${money(materialDefaults(m).price)} /kg ${m.assumedPriceUpdatedAt?'benchmark-adjusted':'assumed'}`}" title="${num(m.price)>0?'Workshop price entered; automatic updates do not change it.':esc(m.assumedPriceSource||'Online benchmark movements adjust this assumed price when available.')}"></td><td><input class="cell-input" data-table="materials" data-index="${i}" data-key="form" value="${esc(m.form)}"></td><td><input class="cell-input wide" data-table="materials" data-index="${i}" data-key="stockSizes" placeholder="Sizes in mm" value="${esc(m.stockSizes||'')}"></td><td><button class="icon-action" data-remove-row="materials" data-index="${i}" title="Remove material">×</button></td></tr>`).join('');bindInlineTable(tb)}
