  function bindInlineTable(tb){
    tb.addEventListener('change',e=>{
      const el=e.target;if(!el.dataset.table)return;const collection=db[el.dataset.table],row=collection[Number(el.dataset.index)];if(!row)return;
      row[el.dataset.key]=el.type==='number'?num(el.value):el.value;persist();
      if(el.dataset.table==='materials'){
        populateMaterialSelect();$('#material-select').value=estimate.material.id||'';renderDashboard();
        const selected=db.materials.find(x=>x.id===estimate.material.id);if(selected)$('#material-stock-hint').textContent=selected.stockSizes?`Available stock sizes (reference): ${selected.stockSizes}`:'No supplier sizes recorded; add available stock sizes in the Material Database.';
        if(selected){if(estimate.assumptionsApplied)materialChanged();else{estimate.material.density=selected.density;estimate.material.price=selected.price;estimate.material.priceIsAssumed=false;if(estimate.material.scrapAssumed)applyScrapDefaults(selected);$('#density').value=selected.density;$('#price-per-kg').value=selected.price;recalculate()}}
      }
      if(el.dataset.table==='machines'||el.dataset.table==='operations'){
        renderOperationPicker();
        if(estimate.assumptionsApplied&&estimate.operations.some(x=>x.assumed)){const material=db.materials.find(m=>m.id===estimate.material.id);estimate.operations=estimate.operations.map(x=>x.assumed?assumedOperation(material,estimate.material.form,x.id):x);renderSelectedOperations();refreshAutoSummary();recalculate()}
      }
    });
    tb.addEventListener('click',e=>{const b=e.target.closest('[data-remove-row]');if(!b)return;const type=b.dataset.removeRow,i=Number(b.dataset.index);if(confirm(`Remove this ${type==='materials'?'material':type==='machines'?'machine':'operation'}?`)){db[type].splice(i,1);persist();type==='materials'?renderMaterials():type==='machines'?renderMachines():renderOperationTypes();if(type==='materials'){populateMaterialSelect();renderDashboard()}if(type==='operations')renderOperationPicker()}})
  }
