  function localRateDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  async function readInternetJson(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error('HTTP '+response.status);return await response.json()}finally{clearTimeout(timer)}}
  async function fetchDailyCurrencyRates(){const codes=Object.keys(currencyCatalog).filter(code=>code!=='INR'),requestCodes=codes.filter(code=>code!=='AED'&&code!=='SAR'&&code!=='USD'),url='https://api.frankfurter.dev/v2/rates?base=USD&quotes='+requestCodes.map(code=>code.toLowerCase()).join(','),payload=await readInternetJson(url),rows=Array.isArray(payload)?payload:Object.entries(payload.rates||{}).map(([quote,rate])=>({quote,rate,date:payload.date})),quotes=Object.fromEntries(rows.map(row=>[String(row.quote||'').toUpperCase(),Number(row.rate)])),asOf=rows.map(row=>row.date).filter(Boolean).sort().pop();if(!quotes.INR||!asOf||Date.now()-Date.parse(asOf+'T00:00:00Z')>8*86400000)throw new Error('Currency feed returned no recent INR rate.');const rates={...db.settings.exchangeRates,INR:1};let updated=0;for(const code of codes){let unitsPerUsd=quotes[code];if(!(unitsPerUsd>0)&&code==='USD')unitsPerUsd=1;if(!(unitsPerUsd>0)&&code==='AED')unitsPerUsd=3.6725;if(!(unitsPerUsd>0)&&code==='SAR')unitsPerUsd=3.75;if(unitsPerUsd>0){const next=quotes.INR/unitsPerUsd;if(Math.abs(num(rates[code])-next)>1e-10)updated++;rates[code]=next}}return {rates,updated,asOf}}
  async function fetchDailyMaterialBenchmarks(){
    const benchmarks={},failures=[];
    function accept(id,entry){const timestamp=Date.parse(entry?.timestamp||entry?.updatedAt||''),raw=Number(entry?.price),unit=String(entry?.unit||'').toLowerCase();if(!Number.isFinite(timestamp)||Date.now()-timestamp>7*86400000||timestamp-Date.now()>86400000||!(raw>0))return false;let usdPerKg=0;if(/\/(mt|t|ton|tonne)\b|metric ton/.test(unit))usdPerKg=raw/1000;else if(/\/kg\b|kilogram/.test(unit))usdPerKg=raw;else if(/\/lb\b|pound/.test(unit))usdPerKg=raw/2.2046226218;else if(/\/ozt\b|troy ounce/.test(unit))usdPerKg=raw*32.1507466;if(!(usdPerKg>0))return false;benchmarks[id]={usdPerKg,timestamp:new Date(timestamp).toISOString()};return true}
    try{const payload=await readInternetJson('https://rzzro.com/api/prices.json?currency=USD');for(const id of dailyMaterialFeedIds){const entry=payload[id]||payload.data?.[id];if(entry)accept(id,entry)}}catch{}
    const missing=dailyMaterialFeedIds.filter(id=>!benchmarks[id]);if(missing.length){const fallback=await Promise.allSettled(missing.map(async id=>{const payload=await readInternetJson('https://croncopia.com/api/metals/'+id+'.json'),timestamp=Date.parse(payload.timestamp||payload.updatedAt||'');if(!Number.isFinite(timestamp)||Date.now()-timestamp>7*86400000||timestamp-Date.now()>86400000)throw new Error('stale');const p=payload.price||{},usdPerKg=Number(p.kilogram)||(Number(p.metric_ton)/1000);if(!(usdPerKg>0))throw new Error('no USD/kg value');return [id,{usdPerKg,timestamp:new Date(timestamp).toISOString()}]}));fallback.forEach((result,index)=>{if(result.status==='fulfilled')benchmarks[result.value[0]]=result.value[1];else failures.push(missing[index]+': no fresh benchmark')})}
    if(!Object.keys(benchmarks).length)throw new Error(failures.join('; ')||'No fresh material benchmark indexes.');return {benchmarks,failures}
  }
  function materialIndexComponents(material){const name=`${material?.name||''} ${material?.form||''}`.toLowerCase();if(/stainless|duplex/.test(name))return [['steel_hrc',.92],['nickel',.08]];if(/brass/.test(name))return [['copper',.65],['zinc',.35]];if(/bronze/.test(name))return [['copper',.9],['tin',.1]];if(/monel/.test(name))return [['nickel',.7],['copper',.3]];if(/nickel|inconel|hastelloy/.test(name))return [['nickel',1]];if(/alumini?um/.test(name))return [['aluminum',1]];if(/copper/.test(name))return [['copper',1]];if(/zinc|zamak/.test(name))return [['zinc',1]];if(/lead/.test(name))return [['lead',1]];if(/\btin\b/.test(name))return [['tin',1]];if(/steel/.test(name))return [['steel_hrc',1]];return null}
  function materialIndexValue(material,benchmarks){const parts=materialIndexComponents(material);if(!parts)return 0;let total=0;for(const [id,weight] of parts){const record=benchmarks[id],value=num(record?.usdPerKg),stamp=Date.parse(record?.timestamp||'');if(!(value>0)||!Number.isFinite(stamp)||Date.now()-stamp>7*86400000)return 0;total+=value*weight}return total}
  function renderRatesUpdateStatus(message=''){const node=$('#rates-update-status');if(!node)return;if(message){node.textContent=message;return}const settings=db.settings||{},last=settings.ratesLastSuccessAt;if(!last){node.textContent=settings.ratesLastError?'Internet update unavailable; saved rates are still in use.':'Rates check once per day while this page is open.';return}const fx=settings.fxRatesAsOf?dateStamp(settings.fxRatesAsOf):'not updated',metal=settings.materialRatesAsOf?dateStamp(settings.materialRatesAsOf):'not updated',summary=settings.ratesLastSummary||'rates checked';node.textContent='Last update '+new Date(last).toLocaleString('en-IN')+' · '+summary+' · FX '+fx+' · metal indexes '+metal+(settings.ratesLastError?' · Some feeds unavailable.':'')}
