  document.addEventListener('focusout',()=>{if(pendingInternetRateRender)setTimeout(flushPendingRateViews,0)});
  async function refreshInternetRates(force=false){if(internetRateRefreshRunning)return;const today=localRateDay(),lastAttempt=Date.parse(db.settings.ratesLastAttemptAt||'');if(!force&&Date.now()-lastAttempt<4*3600000)return;if(!force&&db.settings.fxRatesCheckedDay===today&&db.settings.materialRatesCheckedDay===today)return;internetRateRefreshRunning=true;const editorDraft=rateEditorDraft(),button=$('#refresh-rates');if(button)button.disabled=true;renderRatesUpdateStatus('Checking public exchange and material benchmarks…');db.settings.ratesLastAttemptAt=new Date().toISOString();persist();try{const results=await Promise.allSettled([fetchDailyCurrencyRates(),fetchDailyMaterialBenchmarks()]);let updatedCurrencyCount=0,updatedMaterialCount=0,baselineCount=0;const failures=[];const fx=results[0];if(fx.status==='fulfilled'){db.settings.exchangeRates=fx.value.rates;db.settings.fxRatesAsOf=fx.value.asOf;db.settings.fxRatesCheckedDay=today;updatedCurrencyCount=fx.value.updated}else failures.push('Currencies: '+(fx.reason?.message||'unavailable'));const market=results[1];if(market.status==='fulfilled'){const previous=db.settings.materialBenchmarkValues||{},next={...previous,...market.value.benchmarks},previousUsdInr=num(db.settings.materialBenchmarkUsdInr),currentUsdInr=num(db.settings.exchangeRates.USD)||exchangeRate('USD');for(const material of db.materials){const oldIndex=materialIndexValue(material,previous),newIndex=materialIndexValue(material,next);if(!(newIndex>0))continue;if(oldIndex>0&&previousUsdInr>0){const ratio=(newIndex*currentUsdInr)/(oldIndex*previousUsdInr);if(Number.isFinite(ratio)&&ratio>.5&&ratio<2&&Math.abs(ratio-1)>.00005){const fallback=materialAssumptions[materialClass(material)]||materialAssumptions.steel,basePrice=num(material.assumedPrice)||fallback.price;material.assumedPrice=Number((basePrice*ratio).toFixed(4));material.assumedPriceUpdatedAt=new Date().toISOString();material.assumedPriceSource='Daily online commodity benchmark';updatedMaterialCount++}}else baselineCount++}db.settings.materialBenchmarkValues=next;db.settings.materialBenchmarkUsdInr=currentUsdInr;db.settings.materialRatesAsOf=Object.values(market.value.benchmarks).map(item=>item.timestamp).sort().pop();db.settings.materialRatesCheckedDay=today;if(market.value.failures.length)failures.push('Some material indexes were unavailable or stale')}else failures.push('Materials: '+(market.reason?.message||'unavailable'));if(fx.status==='fulfilled'||market.status==='fulfilled'){db.settings.ratesLastSuccessAt=new Date().toISOString();db.settings.ratesLastError=failures.join('; ');const summary=[];if(fx.status==='fulfilled')summary.push('FX refreshed');if(market.status==='fulfilled')summary.push('metal indexes refreshed');if(updatedMaterialCount)summary.push(updatedMaterialCount+' assumed material rates adjusted');else if(baselineCount)summary.push('material benchmark baseline saved');db.settings.ratesLastSummary=summary.join(' · ')||'rates checked'}else db.settings.ratesLastError=failures.join('; ');if(updatedMaterialCount&&estimate.material.priceIsAssumed){const selected=db.materials.find(m=>m.id===estimate.material.id);if(selected){estimate.material.price=baseCurrencyToCurrent(num(selected.assumedPrice)||materialDefaults(selected).price);if(estimate.material.scrapAssumed)applyScrapDefaults(selected)}}persist();if(fx.status==='fulfilled'||updatedMaterialCount){if(document.activeElement?.matches('input,select,textarea')){pendingInternetRateRender=true;pendingRateEditorDraft=editorDraft}else{renderCurrencyDependentViews();restoreRateEditorDraft(editorDraft)}}renderRatesUpdateStatus();if(force)toast(db.settings.ratesLastError?'Rates updated with some feeds unavailable.':updatedCurrencyCount||updatedMaterialCount?'Internet rates refreshed.':'Internet benchmarks checked; no new market movement.')}catch(error){db.settings.ratesLastError=error?.message||'Internet rate refresh failed.';persist();renderRatesUpdateStatus()}finally{internetRateRefreshRunning=false;if(button)button.disabled=false}}  function syncCurrencyChrome(){const code=currencyCode();$('#currency-pill-label').textContent=`${code} · ${db.settings.location||'India'}`;$('#metric-currency-icon').textContent=currencySymbol();$$('.currency-code-label').forEach(el=>el.textContent=code);$('#rate-reference-symbol').textContent=currencySymbol();$('#conventional-rate-total').textContent=money(baseCurrencyToCurrent(455));$('#conventional-rate-breakdown').textContent=`${money(baseCurrencyToCurrent(250))} machine · ${money(baseCurrencyToCurrent(180))} labour · ${money(baseCurrencyToCurrent(25))} energy`;$('#cnc-rate-total').textContent=money(baseCurrencyToCurrent(700));$('#cnc-rate-breakdown').textContent=`${money(baseCurrencyToCurrent(450))} machine · ${money(baseCurrencyToCurrent(200))} labour · ${money(baseCurrencyToCurrent(50))} energy`;$('#setting-currency').value=code;updateCurrencyRateEditor();syncWorkspaceIdentity()}
